/* Signature Hmong Names Database — name-meaning lookup demo (jahdb-demo-1.0)
 * RUN ON PC: save as demo.js, then run:  node demo.js [name]
 * RUN IN BROWSER: paste into the console and press Enter. */
var TABLE = {"Pajhuab": "From paj (flower) + huab (colorful?): 'flower hues'.", "Maivang": "From Mai + vang.", "Toulom": "From Tou + lom (round/full?).", "Ntxawmpaj": "From Ntxawm + paj (flower).", "Chuevang": "From Chue + vang.", "Yerlom": "From Yer + lom.", "Pajvang": "Signature clan-style surname combining paj and vang.", "Mailee": "Signature clan-style surname.", "Touxiong": "Signature clan-style surname.", "Ntxawmmoua": "Signature clan-style surname."};
function lookup(q){
  q=String(q||'').toLowerCase().trim();
  var keys=Object.keys(TABLE);
  for(var i=0;i<keys.length;i++){ if(keys[i].toLowerCase()===q) return keys[i]+' — '+TABLE[keys[i]]; }
  var hits=keys.filter(function(k){return k.toLowerCase().indexOf(q)>=0;});
  if(!hits.length) return 'No match for "'+q+'". Try: '+keys.slice(0,5).join(', ');
  return hits.map(function(k){return k+' — '+TABLE[k];}).join('\n');
}
var q=(typeof process!=='undefined'&&process.argv[2])||'Pajhuab';
console.log(lookup(q));

